from pathlib import Path
from html import escape
import json
root=Path(__file__).resolve().parents[1]
def page(path,title,description,body,scripts=''):
 target=root/path/'index.html';target.parent.mkdir(parents=True,exist_ok=True)
 canonical='https://angsumi.online/'+path+'/'
 schema={'@context':'https://schema.org','@type':'WebPage','name':title,'description':description,'url':canonical}
 html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} | ANGSUMI</title><meta name="description" content="{escape(description,quote=True)}"><link rel="canonical" href="{canonical}"><meta property="og:title" content="{escape(title,quote=True)}"><meta property="og:description" content="{escape(description,quote=True)}"><meta property="og:type" content="website"><meta property="og:url" content="{canonical}"><meta property="og:image" content="https://angsumi.online/og-icon.png"><link rel="icon" href="/favicon.ico"><link rel="stylesheet" href="/assets/growth.css"><script type="application/ld+json">{json.dumps(schema)}</script><script defer src="/assets/analytics-consent.js"></script>{scripts}</head><body class="growth"><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="/">ANGSUMI</a><nav aria-label="Main navigation"><a href="/services/">Services</a><a href="/portfolio/">Work &amp; methods</a><a href="/resources/">Resources</a><a href="/training/">Learn</a><a href="/inquiry/">Start a project ↗</a></nav></header><main id="main">{body}</main><footer><p><strong>ANGSUMI — The Researcher Who Builds</strong><br>Research | Data | Impact</p><p><a href="/privacy-policy/">Privacy</a> · <a href="/terms/">Terms</a> · <a href="https://wa.me/917896595109">WhatsApp</a> · <a href="/about/">About ANGSUMI</a></p></footer></body></html>'''
 target.write_text(html)

field_counts={}
def field(name,label,kind='text',required=False,options=None,detail=False):
 req=' required' if required else '';detail=' data-detail' if detail else '';id='intake-'+name
 field_counts[name]=field_counts.get(name,0)+1
 if field_counts[name]>1:id+='-'+str(field_counts[name])
 if options:
  control=f'<select id="{id}" name="{name}"{req}{detail}>'+''.join(f'<option value="{escape(v)}">{escape(t)}</option>' for v,t in options)+'</select>'
 elif kind=='textarea':control=f'<textarea id="{id}" name="{name}" maxlength="3000" minlength="10"{req}{detail}></textarea>'
 else:control=f'<input id="{id}" name="{name}" type="{kind}" maxlength="{254 if kind=="email" else 120}"{req}{detail}'+ (' autocomplete="name"' if name=='name' else ' autocomplete="email"' if name=='email' else ' autocomplete="tel"' if name=='phone' else '')+'>'
 return f'<div class="field"><label for="{id}">{label}</label>{control}</div>'
optional=lambda n,l:field(n,l+' (optional)',detail=True)
research=optional('institution','Institution')+optional('field','Research field')+optional('project_type','Project type')+optional('dataset_type','Dataset type')+optional('samples','Number of samples')+field('stage','Current stage (optional)',options=[('','Not sure yet'),('planning','Planning the study'),('data_ready','Data ready'),('analysis_started','Analysis started'),('interpretation','Need interpretation')],detail=True)+optional('deliverables','Required deliverables')+field('deadline','Expected deadline (optional)','date',detail=True)
digital=optional('business_type','Business type')+optional('business_name','Business name')+optional('platform','Website, web portal or mobile app')+optional('workflow','Current workflow')+optional('functionality','Essential functionality')+field('stage','Requirements readiness (optional)',options=[('','Exploring'),('requirements_ready','Requirements ready'),('planning','Need help scoping')],detail=True)+field('deadline','Expected launch date (optional)','date',detail=True)
training=field('level','Current level (optional)',options=[('','Choose if useful'),('beginner','Beginner'),('some_experience','Some experience'),('advanced','Advanced')],detail=True)+optional('interest','Course or workshop interest')+field('format','Preferred format (optional)',options=[('','No preference'),('live','Live online'),('self_paced','Self-paced'),('institution','Institutional workshop')],detail=True)+optional('availability','Availability')
body='''<div class="eyebrow">A conversation starts here</div><h1>Tell us what you’re working on.</h1><p class="intro">A few details help us ask better questions. You can request a conversation without uploading confidential data.</p><p class="help">Only your pathway, goal, name, email and permission to reply are required.</p><div class="steps" aria-label="Inquiry progress"><span data-step-label aria-current="step">01 Your goal</span><span data-step-label>02 Useful context</span><span data-step-label>03 Contact &amp; send</span></div><div class="progress" aria-hidden="true"><span id="progress-bar" style="width:33%"></span></div><form id="intake" novalidate><fieldset data-step><legend>Your goal</legend>'''+field('category','Which pathway fits?',required=True,options=[('research','Research & bioinformatics'),('digital','Digital systems & software'),('training','Education & training')])+field('description','What would you like help with?','textarea',True)+'''<p class="help">At least 10 characters. Describe the problem, without patient records, identity numbers or confidential research findings.</p></fieldset><fieldset data-step hidden><legend>Useful context</legend><p>These questions are optional. Skip anything you haven’t decided.</p><div data-category="research">'''+research+'''</div><div data-category="digital" hidden>'''+digital+'''</div><div data-category="training" hidden>'''+training+'''</div>'''+field('budget','Approximate budget (optional)',options=[('not_sure','Not sure / discuss scope'),('under_5000','Under ₹5,000'),('5000_15000','₹5,000–₹15,000'),('15000_50000','₹15,000–₹50,000'),('50000_plus','₹50,000+')])+'''<p class="help">Budget helps us discuss a suitable scope. It never automatically disqualifies an inquiry.</p></fieldset><fieldset data-step hidden><legend>Contact &amp; permission</legend><div class="row">'''+field('name','Your name',required=True)+field('email','Email address','email',True)+'''</div>'''+field('phone','WhatsApp / phone (optional)','tel')+'''<div class="trap" aria-hidden="true"><label for="website">Leave empty</label><input id="website" name="website" tabindex="-1" autocomplete="off"></div><label class="check"><input type="checkbox" name="contact_consent" required><span>You may use these details to respond to this inquiry. I have read the <a href="/privacy-policy/">privacy notice</a>.</span></label><label class="check"><input type="checkbox" name="marketing_consent"><span>Also send me relevant resources and project follow-ups. This is optional; I can unsubscribe.</span></label><p class="help">Your inquiry is reviewed by ANGSUMI. No payment is collected. Files are not accepted here. We’ll agree any secure transfer separately.</p></fieldset><div class="actions"><button id="back" type="button" class="secondary" hidden>Back</button><button id="next" type="button">Continue →</button><button id="send" type="submit" hidden>Send my inquiry →</button></div></form><div id="intake-status" role="status" aria-live="polite"></div><section id="success" class="result" tabindex="-1" hidden><div class="eyebrow">Inquiry saved</div><h2>Thank you. We have your brief.</h2><p>Your reference: <strong id="lead-reference"></strong></p><p>We’ll review your goals and contact you about scope and next steps. Email delivery depends on our notification service; the reference confirms your inquiry is stored.</p><a href="/resources/">Explore useful resources →</a></section><noscript><p>JavaScript is required for this form. Use the existing inquiry form or WhatsApp below.</p></noscript><p class="help">Prefer a direct conversation? <a href="https://wa.me/917896595109?text=Hello%20ANGSUMI%2C%20I%20would%20like%20to%20discuss%20a%20project.">WhatsApp ANGSUMI</a> · <a href="/#cta">Existing inquiry form</a></p>'''
page('inquiry','Discuss a research, digital or training project','A short project intake for research analysis, digital systems and training. Optional scoping questions; no confidential files required.',body,'<script defer src="/assets/lead-runtime.js"></script><script defer src="/assets/intake.js"></script>')
services=[
('rna-seq-analysis','RNA-seq analysis services','Have sequencing data but need a defensible analysis plan?','We scope analysis around your biological question, study design and available reference. A count matrix alone cannot replace experimental context.',['Study-design and input audit','Read QC and alignment or quantification plan','Count-based differential expression with appropriate design','Exploratory visualization and functional interpretation','Versioned scripts, provenance and a limitations report'],'MD_RNAseq','research-checklist'),
('metagenomics-analysis','Metagenomics analysis services','Unsure which microbiome workflow fits your samples?','Amplicon profiling and shotgun metagenomics answer different questions. We first review assay type, controls, metadata and reference coverage.',['Assay and sample-metadata review','Quality control and contamination assessment plan','Taxonomic profiling or assembly strategy','Diversity analysis appropriate to design','Reproducible workflow and interpretation notes'],'MD_Metagenome','research-checklist'),
('bioinformatics-consulting','Bioinformatics consulting','Need an independent plan before committing to analysis?','Bring your research question, available data types and the decisions you need to make. We can scope a focused review or a complete computational workflow.',['Question and feasibility review','Method and tool selection with assumptions','Compute and reference-data requirements','Deliverable checklist and reproducibility plan','Written scope before work begins'],'bioinformatics','bioinformatics-labs'),
('scientific-data-analysis','Scientific data analysis','Your dataset is ready. Is the analysis design?','We help researchers clean, explore and model data in Python or R, with clear assumptions and reproducible outputs.',['Data dictionary and quality checks','Exploratory analysis and missingness review','Statistical model matched to study design','Sensitivity checks and interpretation','Code, figures and a limitations report'],'MD_RNAseq','research-checklist'),
('scientific-figure-preparation','Scientific figure preparation','Need figures that explain the result clearly?','We turn documented analysis outputs into readable scientific figures. Figure preparation does not change or manufacture the underlying evidence.',['Review of data and intended message','PCA, heatmap, volcano or other suitable plots','Legible labels and accessible color choices','Vector or high-resolution exports as agreed','Reusable plotting code and figure notes'],'MD_RNAseq','research-checklist'),
('python-research-automation','Python for research automation','Repeating the same data task by hand?','We scope scripts around a documented input/output contract, so recurring data work can be repeated and checked.',['Workflow and bottleneck review','Input validation and failure handling','Reusable scripts with configuration','Representative checks and documentation','Handover and maintenance scope'],'MD_Metagenome','research-checklist')]
for slug,title,problem,desc,deliverables,repo,campaign in services:
 body=f'<div class="eyebrow">Research &amp; bioinformatics</div><h1>{problem}</h1><p class="intro">{desc}</p><div class="actions"><a class="btn" data-growth-event="cta_click" data-category="research" href="/inquiry/?category=research">Discuss a Research Project →</a><a class="btn secondary" href="/resources/">Start with a free checklist</a></div><section><h2>{title}</h2><div class="grid"><article class="card"><h3>What you receive</h3><ul>'+''.join('<li>'+d+'</li>' for d in deliverables)+'</ul></article><article class="card"><h3>How the work happens</h3><ol><li>Review your question and inputs without collecting confidential files in the inquiry form.</li><li>Agree methods, deliverables, compute, revisions and acceptance checks in writing.</li><li>Run the workflow with recorded versions and input provenance.</li><li>Review outputs, explain limitations and hand over agreed materials.</li></ol></article></div></section><section><h2>Scope before a price.</h2><p>A focused review, complete analytical workflow and custom computational project have different requirements. Sample count, assay, reference quality, compute, urgency and interpretation affect the scope. Request an itemized quote; prices and timelines are agreed after assessment.</p><p>Analysis cannot guarantee publication, statistical significance or biological validation.</p></section><section><h2>Explore the methods.</h2><p>The <a href="https://github.com/Angsumi/'+repo+'">'+repo+' repository</a> provides source-level context. Published files are not a claim of a client’s endorsement or permission for reuse. See our <a href="/portfolio/">methods and project index</a> for evidence and limitations.</p></section><section><h2>Common questions</h2><details><summary>Can I inquire before my data are ready?</summary><p>Yes. Choose your current stage and describe the study question. Feasibility and planning can be scoped separately.</p></details><details><summary>Do I need to upload my dataset?</summary><p>No. Do not send confidential or participant data through the inquiry form. Any transfer is agreed through an appropriate secure route.</p></details><details><summary>What affects cost and turnaround?</summary><p>Data quality and scale, study design, reference resources, compute, deliverables and revisions. We confirm an agreed scope rather than promising a fixed deadline from a short form.</p></details></section><div class="notice"><strong>You do the research. We help your data speak.</strong><p><a href="/inquiry/?category=research">Request a scoped project conversation →</a></p></div>'
 page('services/'+slug,title,desc,body)

